def main():
    T = input()
    N = int(input())
    S = []
    for _ in range(N):
        tmp = input().split()
        del(tmp[0])
        S.append(tmp)

    INF = 10**18
    dp = [([0] + [INF] * len(T)) for _ in range(N + 1)]

    for i in range(1, N + 1):
        dp[i] = dp[i - 1][:]

        for s in S[i - 1]:
            for j in range(len(T) + 1):
                post_len = j + len(s)
                if post_len > len(T):
                    continue

                if T[j:post_len] == s:
                    if j == 0:
                        dp[i][post_len] = 1
                    else:
                        dp[i][post_len] = min(dp[i][post_len], dp[i - 1][j] + 1)

    if dp[N][len(T)] == INF:
        print(-1)
    else:
        print(dp[N][len(T)])

    return
